<!doctype html><html><head><meta charset="utf-8"><title>{{ $order->order_number }}</title><link rel="stylesheet" href="{{ asset('css/hms.css') }}"></head><body class="print-page"><div class="print-toolbar"><button class="btn primary" onclick="window.print()">Print</button><button class="btn" onclick="window.close()">Close</button></div><div class="receipt"><h1>{{ $order->property?->name }}</h1><p>{{ $order->outlet?->name }}<br>{{ $order->order_number }}<br>{{ $order->opened_at?->format('d M Y · h:i A') }}</p><div class="receipt-meta"><span>Service</span><b>{{ ucfirst(str_replace('_',' ',$order->service_type)) }}</b>@if($order->table)<span>Table</span><b>{{ $order->table->name }}</b>@endif @if($order->room_number)<span>Room</span><b>{{ $order->room_number }}</b>@endif<span>Cashier</span><b>{{ $order->openedBy?->name }}</b></div><hr>@foreach($order->items as $i)<div class="receipt-line"><div><b>{{ rtrim(rtrim(number_format((float)$i->quantity,3),0),'.') }} × {{ $i->item_name }}</b>@if($i->modifiers->count())<small>{{ $i->modifiers->pluck('name')->join(', ') }}</small>@endif</div><b>{{ number_format((float)$i->line_total) }}</b></div>@endforeach<hr><div class="receipt-total"><span>Subtotal</span><b>{{ number_format((float)$order->subtotal) }}</b></div><div class="receipt-total"><span>Tax/SC</span><b>{{ number_format((float)$order->tax_total+(float)$order->service_charge_total) }}</b></div><div class="receipt-total"><span>TOTAL</span><b>UGX {{ number_format((float)$order->grand_total) }}</b></div><div class="receipt-total"><span>Paid</span><b>{{ number_format((float)$order->paid_total) }}</b></div><hr>@foreach($order->payments as $p)<div class="receipt-line"><span>{{ ucwords(str_replace('_',' ',$p->method)) }}</span><b>{{ number_format((float)$p->amount) }}</b></div>@endforeach<p>Thank you for visiting us.</p></div></body></html>
